<div class="page-actions"><form class="filter-bar" method="get"><div class="input-icon"><i class="bi bi-search"></i><input class="form-control" name="q" placeholder="Cari perusahaan..." value="<?= e($q) ?>"></div><button class="btn btn-light">Cari</button></form><?php if(can('company.manage')):?><a class="btn btn-primary" href="<?= url('/companies/create') ?>"><i class="bi bi-plus-lg me-1"></i>Tambah PT</a><?php endif;?></div>
